package com.nigson.commerce.payment;
import java.util.*;
import java.time.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
/** Stable provider-object dedup preserves the first body; variants are separately quarantined. */
public final class JdbcWebhookReceipts implements WebhookReceipts {
 private final JdbcTemplate jdbc;private final Clock clock;
 public JdbcWebhookReceipts(JdbcTemplate jdbc,Clock clock){this.jdbc=jdbc;this.clock=clock;}
 private void transaction(){if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("LOCAL_TRANSACTION_REQUIRED");}
 private Receipt find(UUID id,boolean lock){var rows=jdbc.queryForList("SELECT id,event_key,body_hash,state,rejection_code,version FROM commerce.webhook_receipt WHERE id=?"+(lock?" FOR UPDATE":""),id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var r=rows.getFirst();return new Receipt(id,r.get("event_key").toString(),r.get("body_hash").toString(),r.get("state").toString(),(String)r.get("rejection_code"),((Number)r.get("version")).longValue());}
 private Stored insert(UUID id,String account,String key,String hash,byte[] ciphertext,String state,String rejection){if(account==null||!account.matches("[A-Za-z0-9][A-Za-z0-9_./:-]{0,99}")||key==null||key.length()>200||hash==null||!hash.matches("[a-f0-9]{64}")||ciphertext==null||ciphertext.length==0||ciphertext.length>350000)throw ApiValues.invalid();ApiValues.uuid(id==null?null:id.toString());var created=jdbc.query("INSERT INTO commerce.webhook_receipt(id,created_by,updated_by,provider,merchant_account,event_key,body_hash,payload_ciphertext,verified_signature,received_at,state,rejection_code) VALUES (?,'paystack-receipt','paystack-receipt','PAYSTACK',?,?,?,?,true,?,?,?) ON CONFLICT(provider,merchant_account,event_key) DO NOTHING RETURNING id",(r,n)->r.getObject(1,UUID.class),id,account,key,hash,ciphertext,java.sql.Timestamp.from(clock.instant()),state,rejection);if(!created.isEmpty())return new Stored(find(id,false),true);UUID previous=jdbc.queryForObject("SELECT id FROM commerce.webhook_receipt WHERE provider='PAYSTACK' AND merchant_account=? AND event_key=?",UUID.class,account,key);return new Stored(find(previous,true),false);}
 public Stored receive(UUID id,String account,PaystackWebhookProtocol.Event event,byte[] ciphertext){transaction();String reason=!event.matchingMode()?"PROVIDER_MODE_MISMATCH":!event.recognized()?"UNSUPPORTED_EVENT":null;var result=insert(id,account,event.eventKey(),event.bodyHash(),ciphertext,reason==null?"RECEIVED":"REJECTED",reason);if(result.receipt().bodyHash().equals(event.bodyHash()))return result;String conflict="conflict:"+EventCodec.hash(EventCodec.JSON.valueToTree(Map.of("eventKey",event.eventKey(),"bodyHash",event.bodyHash())));var quarantined=insert(id,account,conflict,event.bodyHash(),ciphertext,"REJECTED","BODY_CONFLICT");if(!quarantined.receipt().bodyHash().equals(event.bodyHash()))throw PaymentValues.rule();return quarantined;}
 public Pending pending(UUID id){var rows=jdbc.queryForList("SELECT merchant_account,body_hash,payload_ciphertext,verified_signature,state FROM commerce.webhook_receipt WHERE id=? AND provider='PAYSTACK'",id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var r=rows.getFirst();if(!Set.of("RECEIVED","RETRY").contains(r.get("state")))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);return new Pending(id,r.get("merchant_account").toString(),r.get("body_hash").toString(),(byte[])r.get("payload_ciphertext"),Boolean.TRUE.equals(r.get("verified_signature")));}
 public List<UUID> pending(int limit){if(limit<1||limit>100)throw ApiValues.invalid();return jdbc.query("SELECT id FROM commerce.webhook_receipt WHERE provider='PAYSTACK' AND state IN ('RECEIVED','RETRY') ORDER BY received_at,id LIMIT ?",(r,n)->r.getObject(1,UUID.class),limit);}
 public Receipt outcome(UUID id,String account,String hash,String state,String rejection,Verification proof){transaction();if(!Set.of("APPLIED","REJECTED","RETRY").contains(state)||state.equals("REJECTED")&&(rejection==null||!Set.of("UNMATCHED_REFERENCE","PROVIDER_MODE_MISMATCH","VERIFICATION_MISMATCH","PAYLOAD_INVALID").contains(rejection))||!state.equals("REJECTED")&&rejection!=null)throw ApiValues.invalid();var before=find(id,true);if(!before.bodyHash().equals(hash)||!Boolean.TRUE.equals(jdbc.queryForObject("SELECT merchant_account=? AND verified_signature FROM commerce.webhook_receipt WHERE id=? AND provider='PAYSTACK'",Boolean.class,account,id)))throw PaymentValues.rule();if(Set.of("APPLIED","REJECTED").contains(before.state()))return before;if(state.equals("APPLIED")){if(proof==null||proof.order()==null||proof.attempt()==null||proof.providerObjectId()==null||!proof.providerObjectId().matches("[A-Za-z0-9][A-Za-z0-9_-]{0,119}")||proof.providerMode()==null||!Set.of("MOCK","TEST","LIVE").contains(proof.providerMode()))throw PaymentValues.rule();String type=before.eventKey().substring(0,before.eventKey().indexOf(':'));String expectedKey=type+":"+EventCodec.hash(EventCodec.JSON.valueToTree(Map.of("event",type,"providerObjectId",proof.providerObjectId())));if(!expectedKey.equals(before.eventKey()))throw PaymentValues.rule();boolean verified;if(proof.refund()==null){if(!type.equals("charge.success"))throw PaymentValues.rule();verified=Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.payment_attempt a JOIN commerce.payment_transaction t ON t.attempt_id=a.id JOIN commerce.sales_order o ON o.id=a.order_id WHERE a.id=? AND o.id=? AND a.provider='PAYSTACK' AND a.merchant_account=? AND a.provider_mode=? AND a.state='SUCCEEDED' AND a.verified_at IS NOT NULL AND t.provider_transaction_id=? AND t.provider_mode=a.provider_mode AND t.provider_status='success' AND t.settled_amount=a.expected_amount AND a.expected_amount=o.grand_total AND a.currency_code=o.currency_code AND t.currency_code=a.currency_code AND a.provider_mode=CASE o.carrier_snapshot->>'mode' WHEN 'SANDBOX' THEN 'TEST' ELSE o.carrier_snapshot->>'mode' END)",Boolean.class,proof.attempt(),proof.order(),account,proof.providerMode(),proof.providerObjectId()));}else{if(!Set.of("refund.pending","refund.processing","refund.processed","refund.failed").contains(type))throw PaymentValues.rule();verified=Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.refund r JOIN commerce.payment_attempt a ON a.id=r.attempt_id JOIN commerce.payment_transaction t ON t.attempt_id=a.id JOIN commerce.sales_order o ON o.id=r.order_id WHERE r.id=? AND r.order_id=? AND r.attempt_id=? AND r.state IN ('PENDING','SUCCEEDED','FAILED') AND r.provider_refund_id=? AND a.provider='PAYSTACK' AND a.merchant_account=? AND a.provider_mode=? AND a.state='SUCCEEDED' AND a.verified_at IS NOT NULL AND t.provider_mode=a.provider_mode AND t.provider_status='success' AND t.settled_amount=a.expected_amount AND a.expected_amount=o.grand_total AND a.currency_code=o.currency_code AND t.currency_code=a.currency_code AND r.currency_code=a.currency_code AND a.provider_mode=CASE o.carrier_snapshot->>'mode' WHEN 'SANDBOX' THEN 'TEST' ELSE o.carrier_snapshot->>'mode' END)",Boolean.class,proof.refund(),proof.order(),proof.attempt(),proof.providerObjectId(),account,proof.providerMode()));}if(!verified)throw PaymentValues.rule();}if(before.version()==Long.MAX_VALUE)throw PaymentValues.rule();if(!before.state().equals(state)||state.equals("RETRY"))jdbc.update("UPDATE commerce.webhook_receipt SET state=?,rejection_code=?,version=version+1,updated_at=?,updated_by='paystack-receipt' WHERE id=?",state,rejection,java.sql.Timestamp.from(clock.instant()),id);return find(id,false);}
}
